  "brief": {
    "title": "American Express (AXP) Historical Stock Performance Report: 1972–2026",
    "one_liner": "A comprehensive analysis of American Express stock performance spanning over 50 years of daily trading data, covering price trends, volatility, dividend history, and key market events.",
    "goal": "Provide investors with a thorough understanding of AXP's long-term stock performance, identify major growth and decline periods tied to economic cycles, evaluate dividend return patterns, and assess the stock's historical risk-return profile to inform forward-looking investment decisions."
  },
