    {
      "section_id": "executive-overview",
      "title": "Executive Overview",
      "objective": "Summarize AXP's overall stock trajectory from 1972 to present, highlighting cumulative returns, the current price relative to historical levels, and key takeaways for investors."
    },
    {
      "section_id": "price-trend-analysis",
      "title": "Long-Term Price Trend Analysis",
      "objective": "Analyze the closing price trend across decades, identifying major bull and bear phases, all-time highs and lows, and compounded annual growth rate (CAGR) over the full period and key sub-periods."
    },
    {
      "section_id": "volatility-risk",
      "title": "Volatility & Risk Assessment",
      "objective": "Examine daily and annualized volatility, maximum drawdowns, and periods of extreme price movement (e.g., 2008 financial crisis, COVID-19 crash), providing a risk profile of the stock."
    },
    {
      "section_id": "volume-analysis",
      "title": "Trading Volume Analysis",
      "objective": "Analyze trading volume trends over time, identify structural shifts in liquidity, and correlate volume spikes with major price events or corporate actions."
    },
    {
      "section_id": "dividends-splits",
      "title": "Dividend History & Stock Splits",
      "objective": "Document the history of dividend payments and stock splits, calculate dividend yield trends over time, and assess AXP's income-generation profile for long-term shareholders."
    },
    {
      "section_id": "decade-comparison",
      "title": "Decade-by-Decade Performance Comparison",
      "objective": "Compare AXP's performance across each decade (1970s, 1980s, 1990s, 2000s, 2010s, 2020s) in terms of returns, volatility, and dividend activity to contextualize performance within broader economic environments."
    }
  ],
  "kpis": [
    {
      "name": "Cumulative Total Return",
      "description": "Total percentage return from the earliest to the latest available closing price, reflecting overall capital appreciation."
    },
    {
      "name": "Compounded Annual Growth Rate (CAGR)",
      "description": "Annualized growth rate of the closing price over the full dataset period."
    },
    {
      "name": "Maximum Drawdown",
      "description": "The largest peak-to-trough decline in closing price, indicating the worst-case loss scenario for a buy-and-hold investor."
    },
    {
      "name": "Annualized Volatility",
      "description": "Standard deviation of daily returns annualized (×√252), measuring the stock's price risk."
    },
    {
      "name": "Total Dividends Paid Per Share",
      "description": "Sum of all recorded dividend payments over the dataset period, representing cumulative income returned to shareholders."
    }
  ],
  "analysis_dimensions": [
    "Date",
    "Close",
    "Volume",
    "Dividends",
    "Stock Splits"
  ]
}

